from collections import defaultdict

def min_cost_to_form_palindrome(N, strings):
    # Dictionary to store the frequency of each character in the first half of the palindrome
    char_count = defaultdict(int)

    # Iterate over each string
    for s, cost in strings:
        # Check if the string can be used to form the first half of the palindrome
        if len(s) % 2 == 0:
            # If the string length is even, it can be used directly
            for char in s:
                char_count[char] += 1
        else:
            # If the string length is odd, we need to check if it can be used
            # We need to ensure that the middle character is used exactly once
            middle_char = s[len(s) // 2]
            if s.count(middle_char) == 1:
                for char in s:
                    char_count[char] += 1
            else:
                return -1

    # Calculate the minimum cost
    min_cost = 0
    for char, count in char_count.items():
        min_cost += count * cost

    return min_cost

