def can_win(N, M, S):
    # Create a graph representation
    graph = [[] for _ in range(N + 1)]
    for i in range(N):
        if S[i] == '0':
            for j in range(1, M + 1):
                next_square = i + j
                if next_square <= N:
                    graph[i].append((next_square, j))

    # Priority queue for BFS (min-heap)
    pq = [(0, 0, [])]  # (distance, current_square, sequence)

    visited = set()

    while pq:
        distance, current_square, sequence = heapq.heappop(pq)

        # If we reach the target square, return the sequence
        if current_square == N:
            return sequence

        # If we have already visited this square, skip it
        if current_square in visited:
            continue

        visited.add(current_square)

        # Explore all possible moves from the current square
        for next_square, move in graph[current_square]:
            heapq.heappush(pq, (distance + 1, next_square, sequence + [move]))

    # If no path is found, return -1
    return -1

