import heapq

def find_min_sequence(N, M, S):
    # Initialize DP array with infinity
    dp = [float('inf')] * (N + 1)
    dp[0] = 0

    # Priority queue to store (cost, sequence)
    pq = [(0, [0])]

    while pq:
        current_cost, current_sequence = heapq.heappop(pq)

        # If we've reached the target square, return the sequence
        if current_sequence[-1] == N:
            return ' '.join(map(str, current_sequence))

        # Get the last square in the current sequence
        current_square = current_sequence[-1]

        # Try all possible moves
        for x in range(1, M + 1):
            next_square = current_square + x
            if next_square <= N and S[next_square] == 0:
                new_sequence = current_sequence + [next_square]
                new_cost = current_cost + 1

                # If this is the first time we reach this square with this sequence, or
                # we have a shorter sequence, update the DP table and the priority queue
                if dp[next_square] > new_cost:
                    dp[next_square] = new_cost
                    heapq.heappush(pq, (new_cost, new_sequence))

    # If we exhaust the priority queue without reaching the target, return -1
    return -1

