def count_permutations(n, k):
    MOD = 10**9 + 7

    # If k is greater than n(n+1)/2, return 0
    if k > n * (n + 1) // 2:
        return 0

    # Initialize the dp table
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: dp[0][0] = 1 (identity permutation)
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(k + 1):
            # Case 1: Insert i at the end
            dp[i][j] = dp[i - 1][j]
            # Case 2: Insert i at position j
            if j >= i:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - i]) % MOD

    return dp[n][k]

