def count_permutations(n, k):
    MOD = 10**9 + 7

    # If k is greater than n^2, return 0
    if k > n * n:
        return 0

    # Initialize DP table
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(k + 1):
            for l in range(1, i + 1):
                if j - l + dp[i - 1][j - l] <= k:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - l]) % MOD

    return dp[n][k]

