def construct_sequence(M, K):
    if K == 0:
        # If K is 0, each number from 0 to 2^M - 1 can be paired with itself
        return [i for i in range(2**M)]

    # If K is not 0, construct the sequence by pairing each number i with 2^M - 1 - i
    sequence = []
    for i in range(2**M):
        sequence.append(i)
        sequence.append(2**M - 1 - i)

    # Check if the XOR of the sequence is K
    xor_result = 0
    for num in sequence:
        xor_result ^= num

    if xor_result == K:
        return sequence
    else:
