def count_numbers_with_remainder(S):
    MOD = 10**9 + 7
    n = len(S)

    # Initialize DP array
    dp = [[0] * 13 for _ in range(n + 1)]

    # Base case: empty string
    dp[0][0] = 1

    # Fill the DP array
    for i in range(1, n + 1):
        if S[i - 1].isdigit():
            digit = int(S[i - 1])
            for j in range(13):
                dp[i][j] = (dp[i][j] + dp[i - 1][(j - digit) % 13]) % MOD
        else:
            for j in range(13):
                for k in range(10):
                    dp[i][j] = (dp[i][j] + dp[i - 1][(j - k) % 13]) % MOD

    # Sum up the values in the DP array that are congruent to 5 modulo 13
    result = sum(dp[n][j] for j in range(5)) % MOD

    return result

