def count_valid_integers(S):
    MOD = 10**9 + 7
    n = len(S)

    # Initialize DP table
    dp = [[0] * 13 for _ in range(n + 1)]
    dp[0][0] = 1

    # Iterate over each character in the string
    for i in range(n):
        if S[i] == '?':
            # If the character is '?', consider all digits (0-9)
            for j in range(10):
                for k in range(13):
                    dp[i + 1][(k * 10 + j) % 13] += dp[i][k]
                    dp[i + 1][(k * 10 + j) % 13] %= MOD
        else:
            # If the character is a digit, update the DP table
            digit = int(S[i])
            for k in range(13):
                dp[i + 1][(k * 10 + digit) % 13] += dp[i][k]
                dp[i + 1][(k * 10 + digit) % 13] %= MOD

    # The result is the sum of dp[n][5] for all possible lengths
    result = sum(dp[n]) % MOD
    return result

