from collections import defaultdict, deque

def can_schedule(matches):
    n = len(matches)
    graph = defaultdict(list)

    # Build the graph
    for i in range(n):
        for j in range(1, n):
            graph[i].append(matches[i][j])

    # Check for cycles using DFS
    visited = [False] * n
    stack = []

    def dfs(node):
        visited[node] = True
        stack.append(node)

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor):
                    return True
            elif neighbor in stack:
                return True

        stack.pop()
        return False

    for node in range(n):
        if not visited[node]:
            if dfs(node):
                return False

    # If no cycles, perform topological sort
    in_degree = [0] * n
    for node in range(n):
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    queue = deque([node for node in range(n) if in_degree[node] == 0])
    schedule = []

    while queue:
        node = queue.popleft()
        schedule.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if all players are scheduled
    if len(schedule) == n:
        return len(set(schedule))
    else:
        return -1

