        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor):
                    return True
            elif neighbor in stack:
                return True

        stack.pop()
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i):
                return False

    # Topological sort using Kahn's algorithm
    in_degree = [0] * n
    queue = deque()

    for node in range(n):
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    topological_order = []
    while queue:
        node = queue.popleft()
        topological_order.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if the graph is acyclic
    if len(topological_order) != n:
        return -1

    # Calculate the minimum number of days
    return len(topological_order)

