def can_schedule_tournament(N, matches):
    # Check if the graph is complete
    for i in range(N):
        for j in range(i + 1, N):
            if j not in matches[i]:
                return False
    return True

def min_days_to_schedule_tournament(N, matches):
    if N < 3:
        return -1
    if not can_schedule_tournament(N, matches):
        return -1
    return N

