from collections import defaultdict, deque

def is_possible_to_schedule(N, opponents):
    # Create an adjacency list representation of the graph
    graph = defaultdict(list)
    for i in range(1, N + 1):
        for opponent in opponents[i - 1]:
            graph[i].append(opponent)

    # Check for cycles using DFS
    visited = [False] * (N + 1)
    stack = [False] * (N + 1)

    def dfs(node):
        if stack[node]:
            return True
        if visited[node]:
            return False
        visited[node] = True
        stack[node] = True
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        stack[node] = False
        return False

    for node in range(1, N + 1):
        if not visited[node] and dfs(node):
            return -1

    # Perform topological sort
    in_degree = [0] * (N + 1)
    for node in range(1, N + 1):
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    queue = deque([node for node in range(1, N + 1) if in_degree[node] == 0])
    schedule = []

    while queue:
        node = queue.popleft()
        schedule.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if all nodes are included in the schedule
    if len(schedule) != N:
        return -1

    return len(schedule)

