def dfs(graph, node, colors):
    for neighbor in graph[node]:
        if neighbor in colors:
            if colors[neighbor] == colors[node]:
                return False
        else:
            colors[neighbor] = -colors[node]
            if not dfs(graph, neighbor, colors):
                return False
    return True

