def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def min_cost_to_generate_ratio(N, M_a, M_b, packages):
    # Check if the ratio M_a:M_b is valid
    if gcd(M_a, M_b) != 1:
        return -1

    # Initialize the DP table
    dp = [[[[float('inf')] * (M_b + 1) for _ in range(M_a + 1)] for _ in range(M_b + 1)] for _ in range(M_a + 1)]
    dp[0][0][0][0] = 0

    # Fill the DP table
    for a, b, c in packages:
        for i in range(M_a + 1):
            for j in range(M_b + 1):
                for k in range(i + 1):
                    for l in range(j + 1):
                        if k * a + l * b <= i and k * a + l * b <= j:
                            dp[i][j][k][l] = min(dp[i][j][k][l], dp[i - k * a][j - l * b][k][l] + c)

    # Check if it's possible to achieve the desired ratio
    if dp[M_a][M_b][M_a][M_b] == float('inf'):
        return -1

    return dp[M_a][M_b][M_a][M_b]

