    b = math.sqrt((A[0] - C[0])**2 + (A[1] - C[1])**2)
    c = math.sqrt((A[0] - B[0])**2 + (A[1] - B[1])**2)
    s = (a + b + c) / 2
    return math.sqrt(s * (s - a) * (s - b) * (s - c))

