import math

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def welzl(points, boundary, k):
    if k == 0:
        return boundary
    if k == 1:
        return {points[0]}

    # Try to remove the last point and see if the boundary still contains all points
    boundary_without_last = welzl(points, boundary, k - 1)
    if all(distance(p, boundary_without_last) <= boundary_without_last.radius for p in points):
        return boundary_without_last

    # Choose the point that maximizes the distance to the boundary
    max_distance = -1
    max_point = None
    for p in points:
        if p not in boundary_without_last:
            d = distance(p, boundary_without_last)
            if d > max_distance:
                max_distance = d
                max_point = p

    # Add the chosen point to the boundary
    boundary.add(max_point)
    return welzl(points, boundary, k - 1)

def smallest_enclosing_circle(points):
    if len(points) == 0:
        return None
    if len(points) == 1:
        return {points[0]}

    # Find the two closest points
    min_distance = float('inf')
    closest_pair = None
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            d = distance(points[i], points[j])
            if d < min_distance:
                min_distance = d
                closest_pair = (points[i], points[j])

    # Calculate the radius of the circle passing through the two closest points
    center = ((closest_pair[0][0] + closest_pair[1][0]) / 2, (closest_pair[0][1] + closest_pair[1][1]) / 2)
    radius = min_distance / 2

    # Check if the circle passes through all points
    if all(distance(p, (center[0], center[1])) <= radius for p in points):
        return {center: radius}

    # Use Welzl's algorithm to find the smallest enclosing circle
    boundary = {closest_pair[0], closest_pair[1]}
    return welzl(points, boundary, len(points) - 2)

