    visited = [False] * (n + 1)
    def dfs(node):
        if node == t:
            return True
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor] and dfs(neighbor):
                return True
        return False

    if not dfs(s):
        return -1

    # Calculate the minimum number of ken-ken-pa needed
    # Each ken-ken-pa consists of 3 edges
    # The number of ken-ken-pa is the number of edges in the path divided by 3, rounded up
    path_length = 0
    current_node = s
    while current_node != t:
        path_length += 1
        for neighbor in graph[current_node]:
            if neighbor == t:
                path_length += 1
                break
        current_node = neighbor

    # If the path length is not a multiple of 3, add one more ken-ken-pa
    if path_length % 3 != 0:
        path_length += 1

    return path_length // 3

