import math
from functools import reduce

def lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

def lcm_multiple(numbers):
    return reduce(lcm, numbers)

def find_special_number(N):
    # Calculate the LCM of numbers from 2 to N
    lcm_value = lcm_multiple(range(2, N + 1))

    # Find the smallest x such that x - 1 is the LCM
    x = lcm_value + 1

    # Ensure x is within the range [N, 10^13]
    if x > 10**13:
        x = lcm_value + 1 + (10**13 - lcm_value) % lcm_value

    return x

