def binomial_coefficient(n, k):
    # Initialize a 2D list to store binomial coefficients
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: C(n, 0) = 1
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % (10**9 + 7)

    return dp[n][k]

def sum_of_paths(r1, c1, r2, c2):
    total_sum = 0
    mod = 10**9 + 7

    # Iterate over the range of r and c
    for r in range(r1, r2 + 1):
        for c in range(c1, c2 + 1):
            total_sum = (total_sum + binomial_coefficient(r + c, r)) % mod

    return total_sum

