import math

def binomial_coefficient(n, k):
    return math.comb(n, k)

def sum_of_paths(r1, c1, r2, c2):
    total_sum = 0
    mod = 10**9 + 7

    for i in range(r1, r2 + 1):
        for j in range(c1, c2 + 1):
            total_sum += binomial_coefficient(i + j, i)
            total_sum %= mod

