def reconstruct_choices(dp, N, A, B):
    choices = []
    for i in range(N, 0, -1):
        if dp[i][A][B]:
            if dp[i - 1][A + 1][B - 1]:
                choices.append('AB')
                A += 1
                B -= 1
            elif dp[i - 1][A + 1][B]:
                choices.append('AC')
                A += 1
                B = 0
            elif dp[i - 1][A][B + 1]:
                choices.append('BC')
                A = 0
                B += 1
            A -= 1
            B -= 1
            A += 1
            B += 1
    choices.reverse()
    return choices

