import sys

def can_make_choices(N, A, B, C, events):
    # Initialize DP array
    dp = [[[0 for _ in range(10**9 + 1)] for _ in range(10**9 + 1)] for _ in range(N + 1)]
    dp[0][A][B] = 1  # Starting state

    # Directions for transitions
    directions = {
        'AB': [(1, -1), (-1, 1)],
        'AC': [(1, -1), (-1, 1)],
        'BC': [(1, -1), (-1, 1)]
    }

    # Process each event
    for i, event in enumerate(events):
        for d in directions[event]:
            new_A, new_B = A + d[0], B + d[1]
            if new_A >= 0 and new_B >= 0:
                for new_C in range(10**9 + 1):
                    if new_C >= 0:
                        dp[i + 1][new_A][new_C] += dp[i][A][B]

    # Check if there is a valid state after N choices
    for new_A in range(10**9 + 1):
        for new_B in range(10**9 + 1):
            if dp[N][new_A][new_B] > 0:
                # Print "Yes" and the sequence of choices
                print("Yes")
                for j in range(N):
                    if dp[j + 1][new_A][new_C] > 0:
                        if new_A > 0:
                            print("A")
                            new_A -= 1
                        elif new_B > 0:
                            print("B")
                            new_B -= 1
                        else:
                            print("C")
                            new_C -= 1
                return

    # If no valid state is found, print "No"
    print("No")

