            x = query[1]
            # Place a white stone on (x, 1)
            grid[x-1][0] = 'W'
            # Replace black stones between (x, 1) and the first white stone going right
            for j in range(1, N):
                if grid[x-1][j] == 'W':
                    break
                grid[x-1][j] = 'W'

    # Count the number of black stones left on the grid
    black_stones_count = sum(row.count('B') for row in grid)

    return black_stones_count

