def process_queries(N, Q, queries):
    # Initialize the grid with all black stones
    grid = [['B' for _ in range(N)] for _ in range(N)]

    # Place white stones and replace black stones for each query
    for query in queries:
        if query[0] == 1:
            x = query[1]
            # Place white stone on (1, x)
            grid[0][x-1] = 'W'
            # Replace black stones between (1, x) and the first white stone encountered when moving down
            for i in range(1, N):
                if grid[i][x-1] == 'B':
                    grid[i][x-1] = 'W'
                else:
                    break
        elif query[0] == 2:
            x = query[1]
            # Place white stone on (x, 1)
            grid[x-1][0] = 'W'
            # Replace black stones between (x, 1) and the first white stone encountered when moving right
            for j in range(1, N):
                if grid[x-1][j] == 'B':
                    grid[x-1][j] = 'W'
                else:
                    break

    # Count the number of black stones left on the grid
    black_stones_count = sum(row.count('B') for row in grid)
    return black_stones_count

