def dfs(node, parent, adj, visited, dp):
    visited[node] = True
    dp[node][node] = 1  # Each node is a connected component by itself
    for neighbor in adj[node]:
        if not visited[neighbor]:
            dfs(neighbor, node, adj, visited, dp)
            for u in range(node + 1, neighbor + 1):
                for v in range(neighbor + 1, node + 1):
                    dp[u][v] = dp[u][v] + dp[u][neighbor] + dp[neighbor][v] - dp[u][neighbor] * dp[neighbor][v]
    return dp[node][node]

