def can_form_substring(s, t):
    # If t is empty, it can be repeated any number of times
    if not t:
        return True

    # If s is shorter than t, it cannot be repeated
    if len(s) < len(t):
        return False

    # Initialize the DP table
    dp = [[0] * (len(t) + 1) for _ in range(len(s) + 1)]

    # Fill the DP table
    for i in range(1, len(s) + 1):
        for j in range(1, len(t) + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = 0

    # Find the maximum length of the path
    max_length = max(max(row) for row in dp)

    # If the maximum length is equal to the length of t, it can be repeated
    return max_length == len(t)

def find_max_i(s, t):
    if not can_form_substring(s, t):
        return -1

    # If t can be repeated, find the maximum number of times
    max_i = 0
    for i in range(1, len(s) // len(t) + 1):
        if can_form_substring(s, t * i):
            max_i = i

    return max_i

