from collections import defaultdict, deque

def bfs(graph, start, target, L):
    queue = deque([(start, 0, 0)])  # (current_node, current_fuel, fuel_fills)
    visited = set()

    while queue:
        node, fuel, fills = queue.popleft()

        if node == target:
            return fills

        if (node, fuel) in visited:
            continue
        visited.add((node, fuel))

        for neighbor, distance in graph[node]:
            if fuel + distance <= L:
