def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        parent[rootX] = rootY

def is_bipartite(graph):
    parent = list(range(len(graph)))
    for u in range(len(graph)):
        for v in graph[u]:
            if find(parent, u) == find(parent, v):
                return False
            union(parent, u, v)
    return True

