def min_groups(N, M, friendships):
    # Create an adjacency list representation of the graph
    graph = defaultdict(list)
    for A, B in friendships:
        graph[A].append(B)
        graph[B].append(A)

    # Initialize the color array
    colors = [-1] * (N + 1)

    # Function to perform greedy coloring
    def greedy_coloring():
        for i in range(1, N + 1):
            if colors[i] == -1:
                # Try to color the current vertex with the smallest available color
                for color in range(1, N + 1):
                    if all(colors[neighbor] != color for neighbor in graph[i]):
                        colors[i] = color
                        break

    # Perform the greedy coloring
    greedy_coloring()

    # The number of groups is the number of unique colors used
    return len(set(colors))

