def max_item_sum(R, C, K, items):
    # Initialize the DP table
    dp = [[[0] * 4 for _ in range(C)] for _ in range(R)]

    # Parse the items and store them in a dictionary for quick lookup
    item_map = {}
    for r, c, v in items:
        item_map[(r-1, c-1)] = v

    # Base case: start at (0, 0) with 0 items picked up
    if (0, 0) in item_map:
        dp[0][0][0] = item_map[(0, 0)]

    # Fill the DP table
    for i in range(R):
        for j in range(C):
            if (i, j) in item_map:
                # Try moving from (i-1, j) or (i, j-1)
                if i > 0:
                    dp[i][j][0] = max(dp[i][j][0], dp[i-1][j][0] + item_map[(i, j)])
                if j > 0:
                    dp[i][j][0] = max(dp[i][j][0], dp[i][j-1][0] + item_map[(i, j)])

                # Try moving from (i-1, j) or (i, j-1) with one item picked up
                if i > 0:
                    dp[i][j][1] = max(dp[i][j][1], dp[i-1][j][1] + item_map[(i, j)])
                if j > 0:
                    dp[i][j][1] = max(dp[i][j][1], dp[i][j-1][1] + item_map[(i, j)])

                # Try moving from (i-1, j) or (i, j-1) with two items picked up
                if i > 0:
                    dp[i][j][2] = max(dp[i][j][2], dp[i-1][j][2] + item_map[(i, j)])
                if j > 0:
                    dp[i][j][2] = max(dp[i][j][2], dp[i][j-1][2] + item_map[(i, j)])

                # Try moving from (i-1, j) or (i, j-1) with three items picked up
                if i > 0:
                    dp[i][j][3] = max(dp[i][j][3], dp[i-1][j][3] + item_map[(i, j)])
                if j > 0:
                    dp[i][j][3] = max(dp[i][j][3], dp[i][j-1][3] + item_map[(i, j)])

    # Find the maximum value in the DP table
    max_sum = 0
    for k in range(4):
        max_sum = max(max_sum, dp[R-1][C-1][k])

    return max_sum

