def max_item_sum(R, C, K, items):
    # Create a graph representation of the grid
    graph = defaultdict(list)
    for r, c, v in items:
        graph[(r, c)].append((r, c + 1))
        graph[(r, c)].append((r + 1, c))

    # Initialize DP table
    dp = defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(int))))

    # Start from the top-left corner
    dp[1][1][0][0] = items[0][2]

    # Fill the DP table
    for i in range(1, R + 1):
        for j in range(1, C + 1):
            for k in range(4):
                for m in range(4):
                    if (i, j) in graph:
                        for ni, nj in graph[(i, j)]:
                            if ni <= R and nj <= C:
                                if k < 3:
                                    dp[ni][nj][k + 1][m] = max(dp[ni][nj][k + 1][m], dp[i][j][k][m] + items[ni - 1][nj - 1][2])
                                if m < 3:
                                    dp[ni][nj][k][m + 1] = max(dp[ni][nj][k][m + 1], dp[i][j][k][m] + items[ni - 1][nj - 1][2])

    # Find the maximum sum from the start to the goal
    max_sum = 0
    for k in range(4):
        for m in range(4):
            max_sum = max(max_sum, dp[R][C][k][m])

    return max_sum

