def dfs(graph, responses, assignment, i, visited):
    if i == len(graph):
        return is_valid_assignment(graph, responses)

    if visited[i]:
        return False

    visited[i] = True
    for j in graph[i]:
        if dfs(graph, responses, assignment, j, visited):
            return True
    visited[i] = False
    return False

