def count_ways(N: int, A: List[int], B: List[int]) -> int:
    MOD = 1000000007

    # Create an adjacency list to represent the graph
    graph = defaultdict(list)
    for i in range(N):
        for j in range(N):
            if i != j and A[i] * A[j] + B[i] * B[j] == 0:
                graph[i].append(j)
                graph[j].append(i)

    # Initialize DP table
    dp = [0] * (1 << N)
    dp[0] = 1  # There's one way to choose no sardines

    # Iterate over all subsets
    for mask in range(1, 1 << N):
        for i in range(N):
            if mask & (1 << i):
                # Check if sardine i is not adjacent to any chosen sardine
                if all((mask & (1 << j)) == 0 for j in graph[i]):
                    dp[mask] = (dp[mask] + dp[mask ^ (1 << i)]) % MOD

    return dp[(1 << N) - 1]

