def is_tree(graph, n):
    # Check if the graph is a tree using BFS
    visited = [False] * (n + 1)
    queue = deque([1])
    visited[1] = True
    count = 0

    while queue:
        node = queue.popleft()
        count += 1
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    return count == n

def find_shortest_path(graph, start):
    # Find the shortest path from start to all other nodes using BFS
    visited = [False] * (len(graph) + 1)
    queue = deque([start])
    visited[start] = True
    parent = [-1] * (len(graph) + 1)
    distance = [float('inf')] * (len(graph) + 1)
    distance[start] = 0

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                parent[neighbor] = node
                distance[neighbor] = distance[node] + 1
                queue.append(neighbor)

    return distance

