from collections import defaultdict

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        parent[rootX] = rootY

def kruskal(graph):
    edges = sorted(graph.items(), key=lambda item: item[1])
    parent = {i: i for i in range(1, len(graph) + 1)}
    mst = []
    for edge in edges:
        u, v, weight = edge
        if find(parent, u) != find(parent, v):
            union(parent, u, v)
            mst.append((u, v, weight))
    return mst

def solve(n, m, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append((v, 1))
        graph[v].append((u, 1))

    mst = kruskal(graph)

    if len(mst) != n - 1:
        return "No"

    signposts = {}
    for u, v, _ in mst:
        signposts[u] = v

    for i in range(2, n + 1):
        if i not in signposts:
            return "No"

    return "Yes\n" + "\n".join(map(str, signposts.values()))

