from collections import deque

def paint_grid(H, W, N, a):
    # Initialize the grid with zeros
    grid = [[0] * W for _ in range(H)]

    # Create a list to keep track of the number of squares left to paint for each color
    remaining_squares = [a[i] for i in range(N)]

    # Create a list to keep track of the colors assigned to each square
    color_assignment = [[0] * W for _ in range(H)]

    # Create a queue for BFS
    queue = deque()

    # Start with the first color
    color = 1
    for i in range(H):
        for j in range(W):
            if remaining_squares[color - 1] > 0:
                grid[i][j] = color
                remaining_squares[color - 1] -= 1
                color_assignment[i][j] = color
                queue.append((i, j))

    # Perform BFS to ensure all squares of the same color are connected
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == 0 and remaining_squares[color - 1] > 0:
                grid[nx][ny] = color
                remaining_squares[color - 1] -= 1
                color_assignment[nx][ny] = color
                queue.append((nx, ny))

    # Print the grid
    for row in grid:
        print(' '.join(map(str, row)))

